<?php
require 'config.php'; require_login(); if(!is_admin()) redirect('index.php');
$rows=$pdo->query("SELECT b.*,COALESCE(SUM(CASE WHEN t.jenis_transaksi='masuk' THEN t.jumlah ELSE 0 END),0) masuk,COALESCE(SUM(CASE WHEN t.jenis_transaksi='keluar' THEN t.jumlah ELSE 0 END),0) keluar FROM barang b LEFT JOIN transaksi_barang t ON t.id_barang=b.id_barang GROUP BY b.id_barang ORDER BY b.nama_barang")->fetchAll(PDO::FETCH_ASSOC);
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Laporan Stok</title><link rel="stylesheet" href="style.css"></head><body><?php include 'nav.php'; ?><main class="main"><header class="page-head"><div><p class="eyebrow">REPORT</p><h1>Laporan Stok</h1><p class="muted">Rekap barang dan pergerakan stok.</p></div><button class="btn" onclick="window.print()">Cetak laporan</button></header><section class="panel"><div class="table-wrap"><table><thead><tr><th>Barang</th><th>Kategori</th><th>Stok saat ini</th><th>Barang masuk</th><th>Barang keluar</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= htmlspecialchars($r['nama_barang']) ?></td><td><?= htmlspecialchars($r['kategori']) ?></td><td><?= $r['stok'] ?> <?= htmlspecialchars($r['satuan']) ?></td><td><?= $r['masuk'] ?></td><td><?= $r['keluar'] ?></td><td><?= $r['stok']<=$r['stok_minimum']?'Menipis':'Aman' ?></td></tr><?php endforeach ?></tbody></table></div></section></main></body></html>
